CRGB Crgb565(uint16_t ag){

// 1111'1000'0000'0000 = 0xf800 //5 bits of R
// 0000'0111'1110'0000 = 0x07e0 // 6 bits of G
// 0000'0000'0001'1111 = 0x001f // 5 bits of B

  CRGB col;
  col.r = (byte) ((ag & 0xF800)>>8); // mask out the 5 bits of red at the start of the word, shift it right not for 11 but 9 to make it brighter and take a byte.
  col.g = (byte) ((ag & 0x07E0)>>3); // mask out the 6 bits of blue in the middle of the word, shift it right and take a byte //5
  col.b = (byte) ((ag & 0x001F)<<3); // mask out the 5 bits of green in the end of the word and take a byte
  return col;
}

byte frame = 0;

void DrawEarth(const uint_farptr_t arr1) {
  
  uint16_t  sprite_ptr;
  CRGB col;

  byte frameWidth =  (byte) pgm_read_word_far(arr1 + 0*sizeof(uint16_t));
  byte frameHeight = (byte) pgm_read_word_far(arr1 + 1*sizeof(uint16_t));
  byte frames =      (byte) pgm_read_word_far(arr1 + 2*sizeof(uint16_t));
  

  sprite_ptr = 3 + frameWidth * frameHeight * frame;

  for (byte y = 0; y < 16; y++) { //COLS
    for (byte x = 0; x < 16; x++) { //ROWS
      col = Crgb565(pgm_read_word_far(arr1+sprite_ptr++*sizeof(uint16_t)));      
      leds[XY(x, 15-y)] = col; //COLS-1-y
    }
  }
  
  frame++;
  if (frame >= frames) frame = 0;

 // nscale8(leds, NUM_LEDS, 200);

}

void draw() {
  DrawEarth(earth1616);
  delay(50);
}